document.addEventListener("DOMContentLoaded",()=>{const video=document.getElementById("course-video");const markCompleteBtn=document.getElementById("mark-complete-btn");const youtubeContainer=document.getElementById("youtube-player");function showToast(message,type="success"){const toast=document.createElement("div");const colorClass=type==="success"?"bg-emerald-600":"bg-blue-600";toast.className=`fixed bottom-8 right-8 ${colorClass} text-white px-6 py-4 rounded-xl shadow-2xl transform transition-all duration-500 translate-y-20 opacity-0 z-50 font-bold flex items-center gap-4`;let html=`<i class="fa-solid fa-circle-check text-xl"></i> <div>${message}</div>`;if(NEXT_LESSON_ID){html+=`<a href="/learn/${COURSE_ID}/lesson/${NEXT_LESSON_ID}" class="ml-4 bg-white/20 hover:bg-white/30 text-white px-3 py-1.5 rounded-lg text-xs transition border border-white/20">Next Lesson &rarr;</a>`}toast.innerHTML=html;document.body.appendChild(toast);requestAnimationFrame(()=>{toast.classList.remove("translate-y-20","opacity-0")});setTimeout(()=>{toast.classList.add("translate-y-20","opacity-0");setTimeout(()=>toast.remove(),500)},4e3)}function markSidebarComplete(){const currentPath=window.location.pathname;const activeLink=document.querySelector(`a[href="${currentPath}"]`);if(activeLink){const iconContainer=activeLink.querySelector("div");if(iconContainer){iconContainer.className="mt-0.5 flex-shrink-0";iconContainer.innerHTML=`<div class="w-5 h-5 rounded-full bg-emerald-500/20 text-emerald-500 flex items-center justify-center text-xs animate-bounce"><i class="fa-solid fa-check"></i></div>`;const title=activeLink.querySelector(".font-medium");if(title)title.classList.add("line-through","decoration-zinc-700","text-zinc-500")}}}function trackProgress(verb,meta={}){fetch("/learn/track",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-TOKEN":window.CSRF_TOKEN||""},body:JSON.stringify({lesson_id:LESSON_ID,verb:verb,meta:meta})}).then(response=>response.json()).then(data=>{console.log("Tracked:",verb,data);if(data.status==="success"&&verb==="completed"){markSidebarComplete();showToast("Lesson Completed!","success");if(markCompleteBtn){markCompleteBtn.disabled=true;markCompleteBtn.innerHTML='<i class="fa-solid fa-check mr-2"></i> Completed';markCompleteBtn.classList.add("opacity-50","cursor-not-allowed")}}else if(data.error){console.error("Server Error:",data.error)}}).catch(err=>console.error("Tracking Error:",err))}if(video){let hasStarted=false;let hasHalfway=false;video.addEventListener("play",()=>{if(!hasStarted){trackProgress("started");hasStarted=true}});video.addEventListener("timeupdate",()=>{if(!hasHalfway&&video.duration>0){const percent=video.currentTime/video.duration;if(percent>=.5){trackProgress("watched_50");hasHalfway=true}}});video.addEventListener("ended",()=>{trackProgress("completed")})}if(youtubeContainer){window.ytPlayer=null;let hasStarted=false;let hasHalfway=false;const videoId=youtubeContainer.dataset.videoId;window.onYouTubeIframeAPIReady=function(){window.ytPlayer=new YT.Player("youtube-player",{height:"100%",width:"100%",videoId:videoId,playerVars:{autoplay:1,modestbranding:1,rel:0},events:{onStateChange:onPlayerStateChange}})};if(window.YT&&window.YT.Player){onYouTubeIframeAPIReady()}function onPlayerStateChange(event){if(event.data==YT.PlayerState.PLAYING){if(!hasStarted){trackProgress("started");hasStarted=true}startTimer()}if(event.data==YT.PlayerState.ENDED){trackProgress("completed");stopTimer()}}let timer;function startTimer(){timer=setInterval(()=>{if(!hasHalfway&&window.ytPlayer&&typeof window.ytPlayer.getDuration==="function"){const duration=window.ytPlayer.getDuration();const currentTime=window.ytPlayer.getCurrentTime();if(duration>0&&currentTime/duration>=.5){trackProgress("watched_50");hasHalfway=true}}},1e3)}function stopTimer(){clearInterval(timer)}}if(markCompleteBtn){markCompleteBtn.addEventListener("click",()=>{trackProgress("completed")})}const noteForm=document.getElementById("note-form");const noteContent=document.getElementById("note-content");const timeDisplay=document.getElementById("current-time-display");const timestampBtn=document.getElementById("timestamp-btn");const notesList=document.getElementById("notes-list");let currentTimestamp=0;function formatTime(seconds){const m=Math.floor(seconds/60);const s=Math.floor(seconds%60);return`${m}:${s.toString().padStart(2,"0")}`}function getPlayerTime(){if(video&&!video.paused){return video.currentTime}if(window.ytPlayer&&typeof window.ytPlayer.getCurrentTime==="function"){return window.ytPlayer.getCurrentTime()}if(video)return video.currentTime;return 0}setInterval(()=>{currentTimestamp=getPlayerTime();if(timeDisplay)timeDisplay.textContent=formatTime(currentTimestamp)},1e3);if(timestampBtn){timestampBtn.addEventListener("click",()=>{const timeStr=`[${formatTime(currentTimestamp)}] `;noteContent.value+=timeStr;noteContent.focus()})}function fetchNotes(){if(!notesList)return;fetch(`/notes/lesson/${LESSON_ID}`).then(res=>res.json()).then(notes=>{if(notes.length===0){notesList.innerHTML=`<div class="text-center py-8 text-zinc-600 text-xs">\n                        <i class="fa-solid fa-pencil mb-2 block text-lg"></i>\n                        No notes yet. Start writing!\n                    </div>`;return}notesList.innerHTML=notes.map(note=>`\n                    <div class="bg-zinc-950 border border-zinc-800 p-3 rounded-lg group animate-fade-in">\n                        <div class="flex justify-between items-start mb-1">\n                            <span class="text-xs font-bold text-indigo-400 font-mono cursor-pointer hover:underline" onclick="seekTo(${note.timestamp})">${note.timestamp?formatTime(note.timestamp):"0:00"}</span>\n                            <button onclick="deleteNote(${note.id})" class="text-zinc-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition"><i class="fa-solid fa-times"></i></button>\n                        </div>\n                        <p class="text-sm text-zinc-300 whitespace-pre-wrap leading-relaxed">${escapeHtml(note.content)}</p>\n                    </div>\n                `).join("")})}window.seekTo=function(seconds){if(video){video.currentTime=seconds;video.play()}else if(window.ytPlayer){window.ytPlayer.seekTo(seconds,true);window.ytPlayer.playVideo()}};if(noteForm){noteForm.addEventListener("submit",e=>{e.preventDefault();const content=noteContent.value.trim();if(!content)return;fetch("/notes/store",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-TOKEN":window.CSRF_TOKEN||""},body:JSON.stringify({lesson_id:LESSON_ID,content:content,timestamp:Math.floor(currentTimestamp)})}).then(res=>res.json()).then(data=>{if(data.status==="success"){noteContent.value="";fetchNotes();showToast("Note saved","success")}else{console.error("Save Note Error:",data);showToast(data.message||"Failed to save note","error")}}).catch(err=>{console.error("Network Error:",err);showToast("Network error saving note","error")})})}fetchNotes();function escapeHtml(text){return text.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}window.deleteNote=function(id){if(!confirm("Delete note?"))return;fetch(`/notes/delete/${id}`,{method:"POST",headers:{"X-Requested-With":"XMLHttpRequest","X-CSRF-TOKEN":window.CSRF_TOKEN||""}}).then(res=>res.json()).then(data=>{if(data.status==="success"){fetchNotes();showToast("Note deleted","success")}else{showToast("Failed to delete note","error")}}).catch(err=>{console.error(err);showToast("Error deleting note","error")})}});